// l'ajout au groupe, cf. creerAccesApprenantCore côté backend) - mêmes items/logique que
// l'onglet Suivi démarrage d'Onboarding, portés ici pour le présentiel.
const SUIVI_ITEMS_AUTO = ["bienvenue", "acces"];
const suiviChecklistEffectif = (a) => ({
  ...(a.suivi_checklist || {}),
  bienvenue: !!a.apprenant_id,
  acces:     !!a.apprenant_id,
});
const SUIVI_PAGE_SIZE = 10;
const paginateSuivi = (items, page) => items.slice((page-1)*SUIVI_PAGE_SIZE, page*SUIVI_PAGE_SIZE);
const SuiviPagination = ({ page, setPage, total, color }) => {
  const nb = Math.max(1, Math.ceil(total / SUIVI_PAGE_SIZE));
  if (nb <= 1) return null;
  const pages = [];
  for (let i = 1; i <= nb; i++) {
    if (i === 1 || i === nb || Math.abs(i - page) <= 1) pages.push(i);
    else if (pages[pages.length-1] !== "…") pages.push("…");
  }
  return (
    <div style={{ display:"flex",alignItems:"center",justifyContent:"center",gap:6,marginTop:16 }}>
      <button onClick={()=>setPage(p=>Math.max(1,p-1))} disabled={page===1}
        style={{ padding:"5px 12px",borderRadius:7,border:"1px solid #e2e8f0",background:page===1?"#f8fafc":"#fff",color:page===1?"#cbd5e1":"#374151",fontWeight:700,fontSize:12,cursor:page===1?"default":"pointer" }}>‹</button>
      {pages.map((p,i)=>
        p==="…"
          ? <span key={`e${i}`} style={{ fontSize:12,color:"#9ca3af",padding:"0 2px" }}>…</span>
          : <button key={p} onClick={()=>setPage(p)}
              style={{ width:32,height:32,borderRadius:7,border:`1.5px solid ${page===p?color:"#e2e8f0"}`,background:page===p?color:"#fff",color:page===p?"#fff":"#374151",fontWeight:700,fontSize:12,cursor:"pointer" }}>{p}</button>
      )}
      <button onClick={()=>setPage(p=>Math.min(nb,p+1))} disabled={page===nb}
        style={{ padding:"5px 12px",borderRadius:7,border:"1px solid #e2e8f0",background:page===nb?"#f8fafc":"#fff",color:page===nb?"#cbd5e1":"#374151",fontWeight:700,fontSize:12,cursor:page===nb?"default":"pointer" }}>›</button>
      <span style={{ fontSize:11,color:"#9ca3af",marginLeft:4 }}>{page} / {nb}</span>
    </div>
  );
};

