// Normalise un élément d'horaire : objet {jour,debut,fin} OU chaîne déjà formatée
const fmtHoraire = (h) => {
  if (!h) return "";
  if (typeof h === "string") return h;
  if (typeof h === "object") return `${h.jour || ""} ${h.debut || ""}${h.fin ? "–"+h.fin : ""}`.trim();
  return String(h);
};

// ── Plan mensuel helpers ─────────────────────────────────────────────────────
const MOIS_FR = ["Janvier","Février","Mars","Avril","Mai","Juin","Juillet","Août","Septembre","Octobre","Novembre","Décembre"];
const getMoisLabel = (periode) => { const [y,m] = periode.split("-"); return `${MOIS_FR[parseInt(m,10)-1]} ${y}`; };
// Jour d'échéance ancré sur le vrai jour de départ (ex: démarré le 20 → dû le 20 chaque
// mois), pas toujours le 1er - clampé au dernier jour du mois si celui-ci est plus court
// (ex: ancre au 31, un mois de 30 jours ou février tombe sur son propre dernier jour).
const genererMoisPaiements = (dateDebut, dateFin, mensualite) => {
  if (!dateDebut || !mensualite) return [];
  const mois = [];
  // L'itération interne reste calée au 1er (uniquement pour incrémenter les mois sans bug
  // de débordement de jour, ex: 31 janvier + 1 mois → 3 mars) - le vrai jour d'échéance est
  // stocké une fois pour tout le plan (plan.jour_echeance) et appliqué via dateEcheanceMois().
  const curr = new Date(dateDebut); curr.setDate(1); curr.setHours(0,0,0,0);
  // Plan ouvert (pas de date de fin) : rattrape aussi tous les mois déjà écoulés jusqu'au
  // mois courant inclus (ex: import d'un dossier existant depuis 4 mois) - sinon un seul
  // mois est généré et les versements déjà réalisés n'ont nulle part où s'appliquer ; le
  // cron générerait ensuite les mois suivants comme "en_attente" alors qu'ils sont réglés.
  const limite = dateFin
    ? (() => { const d = new Date(dateFin); d.setDate(1); d.setHours(0,0,0,0); return d; })()
    : (() => { const d = new Date(); d.setDate(1); d.setHours(0,0,0,0); return d; })();
  const MAX  = 60; // sécurité
  let i = 0;
  do {
    const periode = `${curr.getFullYear()}-${String(curr.getMonth()+1).padStart(2,"0")}`;
    mois.push({ id:`m_${periode}`, periode, label:getMoisLabel(periode), montant:mensualite, statut:"en_attente", tranches:[] });
    curr.setMonth(curr.getMonth()+1);
    i++;
  } while (curr <= limite && i < MAX);
  return mois;
};
// Applique les versements déjà importés (montants réels déjà reçus, colonne "Paiements")
// aux premiers mois générés, dans l'ordre chronologique - sans ça, le mois 1 restait
// affiché "en attente" alors que l'argent avait bien été perçu (le versement n'existait
// que dans la liste "Versements enregistrés", jamais rapproché du plan mensuel).
const appliquerVersementsAuPlan = (moisListe, paiements) => {
  const mois = (moisListe || []).map(m => ({ ...m, tranches: [...(m.tranches || [])] }));
  const versements = [...(paiements || [])].sort((a, b) => (a.date || "").localeCompare(b.date || ""));
  let idx = 0;
  for (const pmt of versements) {
    let restant = Number(pmt.montant) || 0;
    while (restant > 0 && idx < mois.length) {
      const m = mois[idx];
      const dejaPaye = (m.tranches || []).reduce((s, t) => s + (t.montant || 0), 0);
      const capacite = Math.max(0, m.montant - dejaPaye);
      if (capacite <= 0) { idx++; continue; }
      const part = Math.min(restant, capacite);
      m.tranches.push({ id: `t_imp_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`, montant: part, statut: "paye", date_paiement: pmt.date || null, mode: "Mobile Money", ref: pmt.reference || "", notes: "Import en masse" });
      restant -= part;
      if (part === capacite) idx++;
    }
  }
  return mois.map(m => {
    const totalPaye = (m.tranches || []).reduce((s, t) => s + (t.montant || 0), 0);
    return { ...m, statut: totalPaye >= m.montant ? "paye" : totalPaye > 0 ? "partiel" : "en_attente" };
  });
};

